import {EquipmentLoadout} from './EquipmentLoadout.js';
export class Character{
 constructor(scene,data,x,y,slots={}){Object.assign(this,{scene,data,id:data.id,x,y,hp:data.hp,special:100,state:'IDLE',direction:'down',stunUntil:0,invulnerableUntil:0,lastAttack:-10000,ko:false,moving:false,hidden:false});this.loadout=new EquipmentLoadout(data,slots);this.size=data.child?72:90;this.texture=data.texture||'duo';this.skin=data.skin||this.id;this.shadow=scene.add.ellipse(x,y,36,13,0x081820,.5);this.sprite=scene.add.image(x,y,this.texture,`${this.skin}-down`).setOrigin(.5,.95).setDisplaySize(this.size,this.size);this.ring=scene.add.ellipse(x,y,44,17).setStrokeStyle(2,0xf7d84a);this.hpBack=scene.add.rectangle(x,y-93,40,4,0x122630);this.hpFill=scene.add.rectangle(x-20,y-93,40,4,0x9dddab).setOrigin(0,.5);this.label=scene.add.text(x,y-105,data.name.toUpperCase(),{fontFamily:'monospace',fontSize:10,color:'#f7eed1'}).setOrigin(.5);}
 get stats(){return this.loadout.stats();}
 face(dx,dy){if(Math.abs(dx)>Math.abs(dy))this.direction=dx<0?'left':'right';else if(dy)this.direction=dy<0?'up':'down';}
 move(dx,dy,dt){this.moving=!!(dx||dy);if(this.ko||this.actionLocked||this.scene.now<this.stunUntil)return;this.face(dx,dy);this.scene.map.move(this,dx*this.stats.speed*dt*(this.scene.now<(this.enemySlowUntil||0)?(this.data.child?.85:.6):1),dy*this.stats.speed*dt*(this.scene.now<(this.enemySlowUntil||0)?(this.data.child?.85:.6):1));this.state=this.moving?'WALK':'IDLE';}
 damage(amount,source){const now=this.scene.now;if(this.ko||now<this.invulnerableUntil)return false;const taken=this.scene.powers?.absorb(this,Math.max(1,amount-this.stats.defense),source)??Math.max(1,amount-this.stats.defense);this.scene.revival?.onHit(this);if(taken<=0)return false;this.hp=Math.max(0,this.hp-taken);this.stunUntil=now+this.scene.difficulty.stun;this.invulnerableUntil=now+this.scene.difficulty.stun+450;this.state='HIT_STUN';this.scene.floatText(this.x,this.y-80,`−${taken}`,'#ffbdad');this.scene.audio.effect('hurt');this.scene.audio.say(this.id,'hurt',0);if(source){const d=Math.hypot(this.x-source.x,this.y-source.y)||1;this.scene.map.move(this,(this.x-source.x)/d*18,(this.y-source.y)/d*18);}if(this.hp<=0){this.ko=true;this.state='KO';this.scene.onKO(this);}return true;}
 celebrate(){this.scene.tweens.killTweensOf(this);this.celebrating=true;this.lootLift=0;this.moving=false;this.scene.tweens.add({targets:this,lootLift:this.scene.app.settings.reduceMotion?0:26,duration:210,yoyo:true,repeat:1,onUpdate:()=>this.render(this===this.scene.player,this.scene.now),onComplete:()=>{this.celebrating=false;this.lootLift=0;this.render(this===this.scene.player,this.scene.now);}});this.render(this===this.scene.player,this.scene.now);}
 render(active,time){for(const v of [this.sprite,this.shadow,this.ring,this.hpBack,this.hpFill,this.label])v.setVisible(!this.hidden);if(this.hidden)return;const bob=this.moving&&!this.ko?Math.sin(time/80)*2:0;this.sprite.setPosition(this.x,this.y+bob-(this.lootLift||0)-(this.kickLift||0)).setTexture(this.celebrating?"celebration":this.texture,this.celebrating?this.skin:`${this.skin}-${this.direction}`).setDepth(this.y).setAlpha(this.ko?.35:time<this.invulnerableUntil&&Math.floor(time/90)%2?.4:1).setAngle(this.ko?80:this.reviveAngle||this.powerAngle|| (this.actionLocked?(this.kickAngle||0):time<this.stunUntil?-7:this.moving?Math.sin(time/100)*2:0));this.shadow.setPosition(this.x,this.y).setDepth(this.y-1);this.ring.setPosition(this.x,this.y).setDepth(this.y-2).setVisible(active&&!this.ko);this.hpBack.setPosition(this.x,this.y-this.size-4).setDepth(this.y+2);this.hpFill.setPosition(this.x-20,this.y-this.size-4).setDisplaySize(40*this.hp/this.data.hp,4).setDepth(this.y+3);this.label.setPosition(this.x,this.y-this.size-17).setDepth(this.y+3);}
}
export class PlayableCharacter extends Character{}
